int fd;
char buf[10];
ssize_t result;

// Syscall: Request file descriptor allocation
fd = open("config.tmp", O_CREAT | O_RDWR, 0644);

if (fd != -1) {
    // Syscall: Data transfer (user space -> kernel space)
    result = write(fd, "SYSTEM", 6);

    // Syscall: Data transfer (kernel space -> user space)
    lseek(fd, 0, SEEK_SET);
    result = read(fd, buf, 6);

    // Syscall: Release resource
    close(fd);
}
